package com.ecole.gestion_scolaire.registration.controller; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.service.RegistrationConsentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/registrations/{registrationId}/consents") public class RegistrationConsentController{private final RegistrationConsentService service;public RegistrationConsentController(RegistrationConsentService s){service=s;}@GetMapping @PreAuthorize("hasAuthority('INSCRIPTION_CONSULTER')") public List<RegistrationConsentResponse> list(@PathVariable Long registrationId){return service.list(registrationId);}@PutMapping @PreAuthorize("hasAuthority('INSCRIPTION_COMPLETER')") public RegistrationConsentResponse save(@PathVariable Long registrationId,@Valid @RequestBody RegistrationConsentRequest r){return service.save(registrationId,r);}}
